use super::*;
use std::os::unix::fs::{DirBuilderExt,PermissionsExt,symlink};
struct Temp{path:PathBuf}
impl Temp{
 fn new()->Self{let path=std::env::temp_dir().join(format!("coucou-terminal-{}",crate::assistant_memory::new_id()));std::fs::DirBuilder::new().mode(0o700).create(&path).unwrap();Self{path}}
 fn tx(&self,restore:bool)->Transaction{
  let path=self.path.join("copy.txt");std::fs::write(&path,b"private fixture content").unwrap();std::fs::set_permissions(&path,std::fs::Permissions::from_mode(0o600)).unwrap();
  let record=Record{id:"copy-id".into(),copy_name:"copy.txt".into(),name:"copy.txt".into(),size:23,kind:"file".into(),entries:1,selected:false,purge_transaction:None};
  let copy=Copy::capture(&self.path,&attachment("ollama","cid",&record,&self.path,"copy.txt"),&mut Budget::new()).unwrap();let mut tx=Transaction::create(&self.path,"ollama","cid",&[record],&[copy]).unwrap();tx.marked().unwrap();tx.move_all().unwrap();
  if restore{tx.restore_moves(&std::collections::BTreeSet::new()).unwrap();tx.restored().unwrap();}else{tx.committed().unwrap();tx.cleanup().unwrap();}tx
 }
 fn root(&self)->PathBuf{self.path.join(CONTROL_ROOT)}
 fn envelope(&self,id:&str)->PathBuf{self.root().join(name(id))}
 fn assert_copy(&self,restore:bool){if restore{assert_eq!(std::fs::read(self.path.join("copy.txt")).unwrap(),b"private fixture content");}else{assert!(!self.path.join("copy.txt").exists());}}
}
impl Drop for Temp{fn drop(&mut self){let _=std::fs::remove_dir_all(&self.path);}}
#[test]fn every_terminal_cleanup_crash_boundary_stays_discoverable_and_reaps_without_data_actions(){
 for restore in [false,true]{for stage in ["terminalPublished","terminalDurable","lockRemoved","payloadRemoved","walRemoved","transactionDirectoryRemoved","transactionDirectoryDurable"]{
  let t=Temp::new();let mut tx=t.tx(restore);let id=tx.id().to_owned();let before=tx.summary().unwrap();assert_eq!(tx.interrupt_metadata(stage).err(),Some("syntheticMetadataInterruption"),"{restore}/{stage}");assert!(t.envelope(&id).exists());drop(tx);
  let inventory=super::super::inventory(&t.path).unwrap();assert!(inventory.unavailable.is_empty(),"{restore}/{stage}: {:?}",inventory.unavailable);assert_eq!(inventory.recoveries.len(),1);assert_eq!(inventory.recoveries[0].id,id);assert_eq!(inventory.recoveries[0].revision,before.revision);assert_eq!(inventory.recoveries[0].phase,before.phase);assert!(Transaction::open(&t.path,&id).is_err());
  let mut terminal=Terminal::open(&t.path,&id).unwrap().unwrap();assert_eq!(terminal.summary().unwrap().provider,"ollama");terminal.remove_metadata().unwrap();terminal.remove_metadata().unwrap();assert!(super::super::inventory(&t.path).unwrap().recoveries.is_empty());assert!(!t.root().join(&id).exists());assert!(!t.envelope(&id).exists());t.assert_copy(restore);
 }}
}
#[test]fn same_owned_handle_retries_uncertain_final_envelope_unlink_without_recreating_anything(){
 for stage in ["terminalRemoved","terminalRemovalDurable"]{let t=Temp::new();let mut tx=t.tx(false);let id=tx.id().to_owned();assert!(tx.interrupt_metadata(stage).is_err());assert!(!t.envelope(&id).exists());assert!(!t.root().join(&id).exists());tx.remove_metadata().unwrap();assert!(super::super::inventory(&t.path).unwrap().recoveries.is_empty());}
}
#[test]fn a_complete_prepublication_stage_keeps_the_wal_and_is_reconciled_as_exact_metadata_only(){let t=Temp::new();let mut tx=t.tx(true);let id=tx.id().to_owned();assert!(tx.interrupt_metadata("terminalStaged").is_err());assert!(!t.envelope(&id).exists());assert!(t.root().join(&id).join("transaction.json").exists());drop(tx);let inventory=super::super::inventory(&t.path).unwrap();assert_eq!(inventory.recoveries.len(),1);assert_eq!(inventory.unavailable.len(),1);let mut tx=Transaction::open(&t.path,&id).unwrap();tx.remove_metadata().unwrap();let inventory=super::super::inventory(&t.path).unwrap();assert!(inventory.recoveries.is_empty());assert!(inventory.unavailable.is_empty());t.assert_copy(true);}
#[test]fn terminalization_does_not_turn_an_old_native_transaction_into_a_payload_permit(){let t=Temp::new();let mut tx=t.tx(true);assert!(tx.interrupt_metadata("terminalDurable").is_err());assert_eq!(tx.current().err(),Some("retentionMetadataOnly"));assert!(tx.source_files().is_err());assert!(tx.move_all().is_err());assert!(tx.cleanup().is_err());t.assert_copy(true);}
#[test]fn replaced_or_symlinked_transaction_directory_is_never_adopted_or_removed(){for link in [false,true]{let t=Temp::new();let mut tx=t.tx(true);let id=tx.id().to_owned();tx.interrupt_metadata("walRemoved").unwrap_err();drop(tx);let old=t.root().join(&id);let moved=t.path.join("original-private-tx");std::fs::rename(&old,&moved).unwrap();if link{symlink(&moved,&old).unwrap();}else{std::fs::DirBuilder::new().mode(0o700).create(&old).unwrap();std::fs::write(old.join("foreign"),b"keep").unwrap();}assert!(Terminal::open(&t.path,&id).is_err());assert!(t.envelope(&id).exists());assert!(old.symlink_metadata().is_ok());t.assert_copy(true);}}
#[test]fn new_payload_or_unknown_metadata_blocks_cleanup_without_touching_foreign_nodes(){for field in ["payload","unknown"]{let t=Temp::new();let mut tx=t.tx(true);let id=tx.id().to_owned();tx.interrupt_metadata("terminalDurable").unwrap_err();drop(tx);let added=if field=="payload"{t.root().join(&id).join("payload").join("foreign")}else{t.root().join(&id).join("foreign")};std::fs::write(&added,b"keep").unwrap();assert!(Terminal::open(&t.path,&id).is_err());assert_eq!(std::fs::read(added).unwrap(),b"keep");t.assert_copy(true);}}
#[test]fn same_bytes_replaced_wal_lock_or_empty_payload_identity_is_not_current(){for field in ["transaction.json",".lock","payload"]{let t=Temp::new();let mut tx=t.tx(true);let id=tx.id().to_owned();tx.interrupt_metadata("terminalDurable").unwrap_err();drop(tx);let old=t.root().join(&id).join(field);let held=t.path.join("held-original-metadata");std::fs::rename(&old,&held).unwrap();if field=="payload"{std::fs::DirBuilder::new().mode(0o700).create(&old).unwrap();}else{std::fs::write(&old,std::fs::read(&held).unwrap()).unwrap();std::fs::set_permissions(&old,std::fs::Permissions::from_mode(0o600)).unwrap();}assert!(Terminal::open(&t.path,&id).is_err(),"{field}");assert!(old.exists());assert!(t.envelope(&id).exists());}}
#[test]fn changed_or_replaced_terminal_record_invalidates_the_captured_native_review(){let t=Temp::new();let mut tx=t.tx(true);let id=tx.id().to_owned();tx.interrupt_metadata("walRemoved").unwrap_err();drop(tx);let mut terminal=Terminal::open(&t.path,&id).unwrap().unwrap();let file=t.envelope(&id);let held=t.path.join("held-proof");std::fs::rename(&file,&held).unwrap();std::fs::write(&file,std::fs::read(held).unwrap()).unwrap();std::fs::set_permissions(&file,std::fs::Permissions::from_mode(0o600)).unwrap();assert!(terminal.remove_metadata().is_err());assert!(file.exists());t.assert_copy(true);}
#[test]fn terminal_records_never_adopt_another_root_scope_or_a_nonterminal_plan(){for change in ["root","phase","hash"]{let t=Temp::new();let mut tx=t.tx(true);let id=tx.id().to_owned();tx.interrupt_metadata("walRemoved").unwrap_err();drop(tx);let file=t.envelope(&id);let mut value:serde_json::Value=serde_json::from_slice(&std::fs::read(&file).unwrap()).unwrap();if change=="root"{value["rootInode"]=0.into();}else if change=="hash"{value["walHash"]="b".repeat(64).into();}else{let mut plan:Plan=serde_json::from_str(value["wal"].as_str().unwrap()).unwrap();plan.phase=Phase::Committed;let wal=serde_json::to_string(&plan).unwrap();value["walHash"]=hash(&wal.as_bytes()).unwrap().into();value["wal"]=wal.into();}std::fs::write(&file,serde_json::to_vec(&value).unwrap()).unwrap();assert!(Terminal::open(&t.path,&id).is_err());assert!(file.exists());t.assert_copy(true);}}
#[test]fn symlink_hardlink_and_unprivate_terminal_files_are_preserved_and_refused(){for mode in ["symlink","hardlink","permissions"]{let t=Temp::new();let mut tx=t.tx(true);let id=tx.id().to_owned();tx.interrupt_metadata("walRemoved").unwrap_err();drop(tx);let file=t.envelope(&id);if mode=="permissions"{std::fs::set_permissions(&file,std::fs::Permissions::from_mode(0o644)).unwrap();}else{let target=t.path.join("held-proof");std::fs::rename(&file,&target).unwrap();if mode=="symlink"{symlink(&target,&file).unwrap();}else{std::fs::hard_link(&target,&file).unwrap();}}assert!(Terminal::open(&t.path,&id).is_err());assert!(file.symlink_metadata().is_ok());}}
#[test]fn partial_or_foreign_staging_metadata_remains_visible_without_being_blindly_erased(){let t=Temp::new();let mut tx=t.tx(true);let foreign=t.root().join(format!("{STAGE}{}",crate::assistant_memory::new_id()));std::fs::write(&foreign,b"partial or foreign metadata").unwrap();std::fs::set_permissions(&foreign,std::fs::Permissions::from_mode(0o600)).unwrap();tx.remove_metadata().unwrap();assert_eq!(std::fs::read(&foreign).unwrap(),b"partial or foreign metadata");let inventory=super::super::inventory(&t.path).unwrap();assert!(inventory.recoveries.is_empty());assert_eq!(inventory.unavailable.len(),1);t.assert_copy(true);}
#[test]fn catalog_inode_replacement_interrupts_cleanup_before_wal_or_payload_is_removed(){let t=Temp::new();let mut tx=t.tx(true);let id=tx.id().to_owned();let path=t.root().join(".catalog.lock");let held=t.path.join("held-catalog");let result=tx.remove_metadata_using(|stage|{if stage=="terminalDurable"{std::fs::rename(&path,&held).unwrap();std::fs::write(&path,b"").unwrap();std::fs::set_permissions(&path,std::fs::Permissions::from_mode(0o600)).unwrap();}Ok(())});assert!(result.is_err());assert!(t.root().join(&id).join("transaction.json").exists());assert!(t.root().join(&id).join("payload").exists());assert!(t.envelope(&id).exists());t.assert_copy(true);}

#[test]fn terminal_envelope_contains_private_metadata_and_the_original_summary_revision_only(){let t=Temp::new();let mut tx=t.tx(false);let before=tx.summary().unwrap();let id=tx.id().to_owned();tx.interrupt_metadata("walRemoved").unwrap_err();drop(tx);let file=t.envelope(&id);let text=std::fs::read_to_string(&file).unwrap();assert!(!text.contains("private fixture content"));assert!(!text.contains(t.path.to_str().unwrap()));assert_eq!(std::fs::metadata(&file).unwrap().mode()&0o777,0o600);let terminal=Terminal::open(&t.path,&id).unwrap().unwrap();assert_eq!(terminal.summary().unwrap().revision,before.revision);}

#[test]fn changed_protocol_or_replaced_namespace_marker_invalidates_a_captured_terminal_review(){for change in ["contents","sameBytes"]{let t=Temp::new();let mut tx=t.tx(true);let id=tx.id().to_owned();tx.interrupt_metadata("walRemoved").unwrap_err();drop(tx);let mut terminal=Terminal::open(&t.path,&id).unwrap().unwrap();let protocol=t.root().join(".protocol.json");if change=="contents"{std::fs::write(&protocol,b"foreign protocol").unwrap();}else{let held=t.path.join("held-protocol");std::fs::rename(&protocol,&held).unwrap();std::fs::write(&protocol,std::fs::read(held).unwrap()).unwrap();std::fs::set_permissions(&protocol,std::fs::Permissions::from_mode(0o600)).unwrap();}assert!(terminal.remove_metadata().is_err());assert!(t.envelope(&id).exists());t.assert_copy(true);}}
#[test]fn replaced_catalog_cannot_be_adopted_on_reopen_even_if_its_contents_match(){let t=Temp::new();let mut tx=t.tx(true);let id=tx.id().to_owned();tx.interrupt_metadata("walRemoved").unwrap_err();drop(tx);let catalog=t.root().join(".catalog.lock");std::fs::rename(&catalog,t.path.join("held-catalog")).unwrap();std::fs::write(&catalog,b"").unwrap();std::fs::set_permissions(&catalog,std::fs::Permissions::from_mode(0o600)).unwrap();assert!(Terminal::open(&t.path,&id).is_err());assert!(t.envelope(&id).exists());t.assert_copy(true);}
